fontFaces.rule:
@font-face {
  font-family: 'Inter Fallback';
  src: local("Arial");
  ascent-override: 90.44%;
  descent-override: 22.52%;
  line-gap-override: 0.00%;
  size-adjust: 107.12%;
}

@font-face {
  font-family: 'JetBrains Mono Fallback';
  src: local("Arial");
  ascent-override: 75.79%;
  descent-override: 22.29%;
  line-gap-override: 0.00%;
  size-adjust: 134.59%;
}
